import { test, expect } from '@playwright/test';

test.describe('Product Sorting by Price - Low to High', () => {
  const BASE_URL = 'https://www.saucedemo.com';
  const USERNAME = 'standard_user';
  const PASSWORD = 'secret_sauce';

  test.beforeEach(async ({ page }) => {
    // Navigate to the application
    await page.goto(BASE_URL);

    // Login with standard_user credentials
    await page.getByLabel('Username').fill(USERNAME);
    await page.getByLabel('Password').fill(PASSWORD);
    await page.getByRole('button', { name: /login/i }).click();

    // Wait for products to load
    await page.waitForSelector('[data-test="inventory-item"]');
  });

  test('should sort products by price in ascending order when selecting lohi option', async ({ page }) => {
    // Get the sort dropdown and select 'lohi' option
    const sortDropdown = page.locator('[data-test="product-sort-container"]');
    await sortDropdown.selectOption('lohi');

    // Wait for the list to reorder
    await page.waitForTimeout(500);

    // Get all price elements
    const priceElements = await page.locator('.inventory_item_price').all();

    // Extract numeric values from price text (e.g., "$9.99" -> 9.99)
    const prices: number[] = [];
    for (const element of priceElements) {
      const priceText = await element.textContent();
      const numericPrice = parseFloat(priceText?.replace('$', '') || '0');
      prices.push(numericPrice);
    }

    // Verify prices are in ascending order
    for (let i = 0; i < prices.length - 1; i++) {
      expect(prices[i]).toBeLessThanOrEqual(prices[i + 1]);
    }
  });

  test('should display at least one product with correct price format after sorting', async ({ page }) => {
    // Select the lohi sort option
    const sortDropdown = page.locator('[data-test="product-sort-container"]');
    await sortDropdown.selectOption('lohi');

    // Wait for sorting to complete
    await page.waitForTimeout(500);

    // Get the first price element
    const firstPrice = page.locator('.inventory_item_price').first();
    const priceText = await firstPrice.textContent();

    // Verify price format is correct (e.g., "$9.99")
    expect(priceText).toMatch(/^\$\d+\.\d{2}$/);

    // Verify the price is a valid number
    const numericPrice = parseFloat(priceText?.replace('$', '') || '0');
    expect(numericPrice).toBeGreaterThan(0);
  });

  test('should maintain sort order when navigating between pages', async ({ page }) => {
    // Select the lohi sort option
    const sortDropdown = page.locator('[data-test="product-sort-container"]');
    await sortDropdown.selectOption('lohi');

    // Wait for sorting to complete
    await page.waitForTimeout(500);

    // Get prices from the current view
    const priceElements = await page.locator('.inventory_item_price').all();
    const prices: number[] = [];

    for (const element of priceElements) {
      const priceText = await element.textContent();
      const numericPrice = parseFloat(priceText?.replace('$', '') || '0');
      prices.push(numericPrice);
    }

    // Verify all prices are in ascending order
    const isSorted = prices.every((price, index) => {
      if (index === 0) return true;
      return price >= prices[index - 1];
    });

    expect(isSorted).toBe(true);
  });
});
